{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Ziprasidone, a lipophilic poorly soluble antipsychotic with piperazine and aryl halides, has an absolute oral bioavailability of about 59-60% in the fed state, directly supporting F >= 20% under the query's fed condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Sertindole, a lipophilic antipsychotic with halophenyl groups, has an oral bioavailability of approximately 74% that is not significantly affected by food, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Asciminib has an absolute human oral bioavailability of approximately 73%, providing a high-transfer direct human measurement supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Rizatriptan has an absolute oral bioavailability of approximately 40% in male volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Apixaban has a human oral bioavailability of 49% at clinically relevant doses, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Compound 26 was predicted to have a human oral bioavailability of 23%, still above the 20% threshold, supporting high with a smaller margin.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is itraconazole, a triazole antifungal. All retrieved human oral bioavailability records, including fed-state ziprasidone (59-60%), sertindole (~74%), asciminib (~73%), rizatriptan (~40%), and apixaban (49%), are above the 20% threshold, and no evidence indicates F < 20%. Fed-state conditions favor absorption, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for itraconazole itself is included in the retrieved evidence; the closest direct condition is fed-state ziprasidone.",
    "Most evidence molecules are structurally unrelated to the query, so transfer relies on general oral-drug behavior rather than azole-specific data.",
    "One supporting record (C20) is a predicted rather than measured human oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

